1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Pulsing Circle</title>
7	  <style>
8	    :root {
9	      --circle-hue: #8ec5ff;
10	      --circle-core: #4a7dd9;
11	      --circle-shadow: #1f3a75;
12	      --cycle: 2.5s;
13	    }
14	    * {
15	      margin: 0;
16	      padding: 0;
17	      box-sizing: border-box;
18	    }
19	    body {
20	      width: 100vw;
21	      height: 100vh;
22	      display: flex;
23	      flex-direction: column;
24	      justify-content: center;
25	      align-items: center;
26	      gap: 24px;
27	      background: radial-gradient(circle at center, #1a1a2e 0%, #0d0d17 100%);
28	      overflow: hidden;
29	    }
30	    svg {
31	      width: min(400px, 80vmin);
32	      height: min(400px, 80vmin);
33	      overflow: visible;
34	      cursor: pointer;
35	      transition: filter 0.3s ease;
36	    }
37	    svg:hover {
38	      filter: brightness(1.08);
39	    }
40	    svg:focus-visible {
41	      outline: 2px solid var(--circle-hue);
42	      outline-offset: 8px;
43	      border-radius: 50%;
44	    }
45	    .ambient {
46	      fill: var(--circle-hue);
47	      opacity: 0.12;
48	      filter: blur(30px);
49	      animation: breathe var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
50	      transform-origin: 200px 200px;
51	      will-change: transform, opacity;
52	    }
53	    .core {
54	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
55	      transform-origin: 200px 200px;
56	      filter: url(#glow);
57	      will-change: transform, opacity;
58	    }
59	    .highlight {
60	      fill: url(#highlightGradient);
61	      transform-origin: 200px 200px;
62	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
63	      pointer-events: none;
64	      will-change: transform, opacity;
65	    }
66	    .ring {
67	      fill: none;
68	      stroke: var(--circle-hue);
69	      stroke-width: 2.5;
70	      transform-origin: 200px 200px;
71	      animation: ripple var(--cycle) cubic-bezier(0.2, 0.6, 0.4, 1) infinite;
72	      will-change: transform, opacity, stroke-width;
73	    }
74	    .ring--delay-1 {
75	      animation-delay: calc(var(--cycle) / 3);
76	    }
77	    .ring--delay-2 {
78	      animation-delay: calc(var(--cycle) / 3 * 2);
79	    }
80	    @keyframes pulse {
81	      0%, 100% {
82	        transform: scale(1);
83	        opacity: 0.9;
84	      }
85	      50% {
86	        transform: scale(1.05);
87	        opacity: 1;
88	      }
89	    }
90	    @keyframes breathe {
91	      0%, 100% {
92	        transform: scale(0.95);
93	        opacity: 0.1;
94	      }
95	      50% {
96	        transform: scale(1.1);
97	        opacity: 0.18;
98	      }
99	    }
100	    @keyframes ripple {
101	      0% {
102	        transform: scale(1);
103	        opacity: 0.6;
104	        stroke-width: 2.5;
105	      }
106	      100% {
107	        transform: scale(1.35);
108	        opacity: 0;
109	        stroke-width: 0.5;
110	      }
111	    }
112	    body.paused .core,
113	    body.paused .ring,
114	    body.paused .ambient,
115	    body.paused .highlight {
116	      animation-play-state: paused;
117	    }
118	    .speed-label {
119	      color: var(--circle-hue);
120	      font-family: system-ui, sans-serif;
121	      font-size: 0.85rem;
122	      letter-spacing: 0.05em;
123	      opacity: 0.7;
124	      user-select: none;
125	      text-align: center;
126	    }
127	    .hint {
128	      display: block;
129	      margin-top: 4px;
130	      font-size: 0.7rem;
131	      opacity: 0.75;
132	    }
133	  </style>
134	</head>
135	<body>
136	  <svg id="ae683f770" viewBox="0 0 400 400" role="button" tabindex="0" aria-label="Pulsing blue circle animation. Click or press Enter to change pulse speed. Press space to pause." aria-describedby="speedText" aria-pressed="false">
137	    <defs>
138	      <radialGradient id="circleGradient" cx="35%" cy="35%" r="65%">
139	        <stop offset="0%" stop-color="#8ec5ff"/>
140	        <stop offset="55%" stop-color="#4a7dd9"/>
141	        <stop offset="100%" stop-color="#1f3a75"/>
142	      </radialGradient>
143	      <radialGradient id="highlightGradient" cx="32%" cy="28%" r="22%">
144	        <stop offset="0%" stop-color="#ffffff" stop-opacity="0.55"/>
145	        <stop offset="100%" stop-color="#ffffff" stop-opacity="0"/>
146	      </radialGradient>
147	      <filter id="glow" x="-80%" y="-80%" width="260%" height="260%">
148	        <feGaussianBlur in="SourceGraphic" stdDeviation="10" result="blur"/>
149	        <feColorMatrix in="blur" type="matrix"
150	          values="0 0 0 0 0.55  0 0 0 0 0.77  0 0 0 0 1  0 0 0 0.9 0" result="tintedBlur"/>
151	        <feMerge>
152	          <feMergeNode in="tintedBlur"/>
153	          <feMergeNode in="SourceGraphic"/>
154	        </feMerge>
155	      </filter>
156	    </defs>
157	    <circle class="ambient" cx="200" cy="200" r="160"/>
158	    <circle class="ring" cx="200" cy="200" r="140"/>
159	    <circle class="ring ring--delay-1" cx="200" cy="200" r="140"/>
160	    <circle class="ring ring--delay-2" cx="200" cy="200" r="140"/>
161	    <circle class="core" cx="200" cy="200" r="140" fill="url(#circleGradient)"/>
162	    <circle class="highlight" cx="200" cy="200" r="140"/>
163	  </svg>
164	  <p class="speed-label" id="speedLabel" aria-live="polite">
165	    <span id="speedText">Normal speed</span>
166	    <span class="hint">Click to change speed · Space to pause</span>
167	  </p>
168	  <script>
169	    const svg = document.getElementById('ae683f770');
170	    const speedText = document.getElementById('speedText');
171	    const speeds = [
172	      { value: '2.5s', name: 'Normal speed' },
173	      { value: '1.2s', name: 'Fast speed' },
174	      { value: '4.5s', name: 'Slow speed' },
175	    ];
176	    let speedIndex = 0;
177	    const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
178	    let manuallyPaused = prefersReducedMotion;
179	
180	    function updateLabels() {
181	      const { name } = speeds[speedIndex];
182	      speedText.textContent = manuallyPaused ? `${name} (paused)` : name;
183	    }
184	
185	    function cycleSpeed() {
186	      speedIndex = (speedIndex + 1) % speeds.length;
187	      const { value } = speeds[speedIndex];
188	      svg.style.setProperty('--cycle', value);
189	      // Restart animations from the beginning so the new speed feels immediate
190	      // instead of jumping mid-cycle.
191	      document.querySelectorAll('.core, .ring, .ambient, .highlight').forEach((el) => {
192	        el.style.animation = 'none';
193	        void el.offsetWidth;
194	        el.style.animation = '';
195	      });
196	      updateLabels();
197	    }
198	
199	    function togglePause() {
200	      manuallyPaused = !manuallyPaused;
201	      document.body.classList.toggle('paused', manuallyPaused);
202	      svg.setAttribute('aria-pressed', String(manuallyPaused));
203	      updateLabels();
204	    }
205	
206	    svg.addEventListener('click', cycleSpeed);
207	    svg.addEventListener('keydown', (e) => {
208	      if (e.key === 'Enter') {
209	        e.preventDefault();
210	        cycleSpeed();
211	      } else if (e.key === ' ') {
212	        e.preventDefault();
213	        togglePause();
214	      }
215	    });
216	
217	    document.addEventListener('visibilitychange', () => {
218	      document.body.classList.toggle('paused', document.hidden || manuallyPaused);
219	    });
220	
221	    document.body.classList.toggle('paused', manuallyPaused);
222	    svg.setAttribute('aria-pressed', String(manuallyPaused));
223	    updateLabels();
224	  </script>
225	</body>
226	</html>
